export function validateResponse(data,id){if(!data||data.request_id!==id)throw Error('Mismatched response request_id');if(!Array.isArray(data.counts)||data.counts.length!==8||data.counts.some(n=>!Number.isInteger(n)||n<0||n>100))throw Error('Expected eight integer spike counts, 0–100');return data.counts}
export function validateEndpoint(value){const url=new URL(value);if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(url.hostname)))throw Error('Use HTTPS, or HTTP on localhost.');if(url.username||url.password)throw Error('Do not include credentials in the URL.');return url.href}
